void slv(){
	int n,m;cin>>n>>m>>base.mod;
	initfact();

	mint ans;
	rng(len,1,m){
		mint f=mint(len+1).pow(len)*len/(n-len)*finv[len];
		rep(i,m-len){
			int j=i+len;
			mint g=mint(n-len).pow(i)*finv[i];
			mint h=(n-j)*mint(n+1).pow(m-1-j)*fact[j];
			ans+=f*g*h;
		}
